-- 웹 푸시(VAPID)용 구독 테이블을 FCM 기기 토큰 테이블로 교체한다 (운영 데이터 없음)
DROP TABLE "push_subscription";

CREATE TABLE "fcm_token" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "token" text UNIQUE NOT NULL,
  "platform" varchar NOT NULL,
  "last_used_at" timestamp NOT NULL,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  "deleted_at" timestamp
);

COMMENT ON TABLE "fcm_token" IS 'FCM 기기 토큰. 사용자당 여러 기기 가능. 무효 토큰은 하드 삭제';
COMMENT ON COLUMN "fcm_token"."platform" IS 'WEB / ANDROID / IOS';
COMMENT ON COLUMN "fcm_token"."last_used_at" IS '마지막 등록·갱신 시각';

ALTER TABLE "fcm_token" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id");
CREATE INDEX idx_fcm_token_user ON "fcm_token" ("user_id");
